import { getTicks } from '@visx/scale';
import { AnyScaleBand } from '@visx/shape/lib/types';
import React from 'react';

import { DivAxisWrapper } from './DivAxisWrapper.js';
import { centerEllipsizeText } from '../../../../../typography/utils.js';
import { getTickValues } from '../../../functions/format-value.js';
import { useComputedFontStyle } from '../../../hooks/useComputedFontStyle.js';
import { AxisLeft } from '../AxisLeft.js';
import { axisFontProps } from '../constants.js';
import { getLeftTickSize } from '../functions/calculate-axis-size.js';
import { getTickLabelPropsForCategoryAxis } from '../functions/get-tick-label-props.js';
import { isTickLabelSpaceAvailable } from '../functions/is-tick-label-visible.js';
import { TickCategory } from '../types.js';

/**
 * @internal
 */
export interface CategoryLeftAxisProps {
  scale: AnyScaleBand;
  containerWidth: number;
  containerHeight: number;
  categories: TickCategory;
  label?: string;
}

const TICK_LABEL_PROPS = getTickLabelPropsForCategoryAxis('left');

/**
 * @internal
 */
export const CategoryLeftAxis = (props: CategoryLeftAxisProps) => {
  const { scale, containerWidth, containerHeight, label, categories } = props;

  const fontStyle = useComputedFontStyle(axisFontProps);
  const ticks = getTicks(scale);
  const tickNames = ticks.map((tickId) => categories[tickId]) ?? 'Unknown';

  const { maxSize, width } = getLeftTickSize(containerWidth, label);

  const truncatedValues = getTickValues(tickNames, (value) =>
    centerEllipsizeText(value.toString(), fontStyle, maxSize),
  );

  const tickFormat = (_: unknown, index: number) => truncatedValues[index];

  const isTickLabelVisible = isTickLabelSpaceAvailable(scale.step());

  return isTickLabelVisible ? (
    <DivAxisWrapper
      divAxisStyle={axisFontProps}
      ticks={tickNames}
      label={label}
    >
      <AxisLeft
        data-testid="category-axis-left"
        scale={scale}
        containerSize={containerHeight}
        width={width}
        tickValues={ticks}
        tickLabelProps={TICK_LABEL_PROPS}
        tickFormat={tickFormat}
        label={label}
      />
    </DivAxisWrapper>
  ) : null;
};

CategoryLeftAxis['displayName'] = 'CategoryLeftAxis';
